def transform(grid):
    h,w=len(grid),len(grid[0]); vals=[v for row in grid for v in row]
    bg=max(set(vals),key=vals.count); mark=next(v for v in vals if v!=bg)
    out=[row[:] for row in grid]
    # Fill enclosed spaces of the mark's connected component using 2, not extending lines
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==mark]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]==bg and (grid[r][c-1]==mark and grid[r][c+1]==mark if 0<c<w-1 else False):
                out[r][c]=2
            if grid[r][c]==bg and (grid[r-1][c]==mark and grid[r+1][c]==mark if 0<r<h-1 else False):
                out[r][c]=2
    return out

