def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    mark = next(v for v in vals if v != bg)
    out = [row[:] for row in grid]
    # Turn to 2 any background cell exactly between two marks in a row or column.
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c-1] == mark and grid[r][c+1] == mark:
                out[r][c] = 2
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == bg and grid[r-1][c] == mark and grid[r+1][c] == mark:
                out[r][c] = 2
    return out
